import math
from itertools import permutations

def get_divisors(m):
    divs = []
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.append(i)
            if i * i != m:
                divs.append(m // i)
    divs.sort()
    return divs

def sigma(m, divisors):
    return sum(divisors)

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def solve_case(m):
    divs = get_divisors(m)
    s_m = sigma(m, divs)

    if not is_perfect_square(s_m):
        return f"m={m}: sigma(m)={s_m}. Not a perfect square. No solution exists."

    # If sigma(m) is a perfect square, we must check for a valid permutation.
    n = len(divs)

    # Since n is very small (max divisors for m<=15 is tau(12)=6 or tau(15)=4), 
    # we can try permutations.

    # We only need to check permutations up to the point where we find one.
    # For small N, iterating through all permutations is feasible.

    found = False
    for p in permutations(divs):
        current_sum = 0
        all_squares = True
        for i in range(n):
            current_sum += p[i]
            if not is_perfect_square(current_sum):
                all_squares = False
                break

        if all_squares:
            found = True
            # Return the permutation for verification/logging
            return f"m={m}: Divisors={divs}. sigma(m)={s_m} (Perfect Square). Valid permutation found: {list(p)}"

    if not found:
        return f"m={m}: Divisors={divs}. sigma(m)={s_m} (Perfect Square). No valid permutation found."


results = []
for m in range(2, 16):
    results.append(solve_case(m))

for res in results:
    print(res)

